      expect(ghostBrideRequestScope(g.world, timed)).toBeUndefined();
    } finally { clock.mockRestore(); }
    expect(request.deadlineAtMs).toBeUndefined();
    expect(brideState(g).remaining).toBe(1);
    return choice(request);
